// Some portions generated by Claude Code
package org.eclipse.rdf4j.workbench.support;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

import jakarta.servlet.http.Cookie;

/** The cookies of a user signed in on the Connection page. */
public final class TestServerCredentials {

	private TestServerCredentials() {
	}

	/** The server credentials cookie for the given user, as the Connection page stores it. */
	public static Cookie[] signedIn(String user) {
		String credentials = Base64.getEncoder()
				.encodeToString((user + ":secret").getBytes(StandardCharsets.ISO_8859_1));
		return new Cookie[] { new Cookie("server-user-password", credentials) };
	}
}
